import Foundation

public enum OutputWriter {
    /// Writes generated files under `directory`. Existing files with the same names are overwritten;
    /// nothing else in the directory is touched or deleted.
    ///
    /// The files hold encoded secrets right next to their salt, so they are as sensitive as the secrets
    /// themselves. Folders created here are readable by their owner only (0700) and so are the files
    /// (0600). A folder that Keychest owns, meaning a new one or one an earlier run generated, is also
    /// excluded from backups on macOS. An unrelated folder that already exists keeps its own permissions
    /// and backup settings.
    @discardableResult
    public static func write(_ files: [GeneratedFile], to directory: String) throws -> [String] {
        let fileManager = FileManager.default
        let root = URL(fileURLWithPath: directory, isDirectory: true)
        let ownerOnlyFolder: [FileAttributeKey: Any] = [.posixPermissions: 0o700]
        var written: [String] = []
        do {
            let existed = fileManager.fileExists(atPath: root.path)
            let ownsRoot = !existed || holdsGeneratedFiles(root)
            if !existed {
                try fileManager.createDirectory(at: root.deletingLastPathComponent(), withIntermediateDirectories: true)
                try fileManager.createDirectory(at: root, withIntermediateDirectories: false, attributes: ownerOnlyFolder)
            } else if ownsRoot {
                try? fileManager.setAttributes(ownerOnlyFolder, ofItemAtPath: root.path)
            }
            if ownsRoot { excludeFromBackups(root) }

            for file in files {
                let url = root.appendingPathComponent(file.path)
                try fileManager.createDirectory(at: url.deletingLastPathComponent(),
                                                withIntermediateDirectories: true,
                                                attributes: ownerOnlyFolder)
                try Data(file.contents.utf8).write(to: url, options: .atomic)
                try fileManager.setAttributes([.posixPermissions: 0o600], ofItemAtPath: url.path)
                written.append(url.path)
            }
        } catch {
            throw KeychestError.writeFailure(error.localizedDescription)
        }
        return written
    }

    /// True when `root` already holds files that Keychest generated on an earlier run.
    private static func holdsGeneratedFiles(_ root: URL) -> Bool {
        [".gitignore", "Package.swift", "build.gradle.kts"].contains { name in
            guard let text = try? String(contentsOf: root.appendingPathComponent(name), encoding: .utf8) else { return false }
            return text.contains("Generated by Keychest")
        }
    }

    /// Keeps the folder out of Time Machine and other backups. Best effort: where the platform has no
    /// such setting, nothing happens.
    private static func excludeFromBackups(_ url: URL) {
        #if canImport(Darwin)
        var url = url
        var values = URLResourceValues()
        values.isExcludedFromBackup = true
        try? url.setResourceValues(values)
        #endif
    }
}
